function isHiddenByPresenceChild(element, presence) {
	for (let el = element; el; el = el.parentElement) if (el.style?.display === "none") return Boolean(presence?.isChild?.(el));
	return false;
}
function isHidden(element) {
	return element.style.display === "none" || element.offsetParent === null && window.getComputedStyle(element).position !== "fixed";
}
